#include "crc.h"
#include "nvfs_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void nvfs_crc_calc_entry_link (NVFS_Entry_Link * const nvfs_entry_link)
{
  UInt16 addr = nvfs_entry_link->addr ;
  UInt16 size = nvfs_entry_link->size ;

  UInt8  crc = NVFS_CRC_INIT ;

  do
    {
      crc_calc_dow_8 (& crc , nvfs_rd_nvram (addr++)) ;
    }
  while (--size) ;

  nvfs_entry_link->crc = crc ;
}

